"""Install run-bound publisher failure diagnostics without bypassing publication checks."""
import os,hashlib,base64,fcntl,subprocess,time,tempfile
from pathlib import Path
MANIFEST={'automation/publish_to_github.ps1': {'old': '22fca9ec1b105e6c5b5242be3872e740f089681f4f0ecc4eefd6825e2c2c7d42', 'new': '26958167384ced88f3a2132377a557a868d021b823777190f030963c21cbaa6b', 'body': ''}, 'automation/server/incident_reports.py': {'old': '71aa3fc5ea6d328145c842a519449d9743426ce27be822830ed4e813ea7a5ec2', 'new': '3db334e76b2a71ac4c7440a1e5ac8314504b891f794caf8667d3ab196483b223', 'body': ''}, 'automation/server/test_incident_reports.py': {'old': '31243d10563cb9939a3f7a7f36d03b398d3bbdc248d62d3514feda6ac351cade', 'new': '57db09b63c22022ae5c7320e745096c314f93a218ed4c7744107d264b83535b1', 'body': ''}, 'automation/server/test_publisher_diagnostics.py': {'old': None, 'new': '3e85eb9efbac2369250dee442b3c5960c3398173136db7d96c8c84f79fc65fc5', 'body': ''}}
def replace(p,raw,stat=None):
    fd,name=tempfile.mkstemp(dir=p.parent,prefix='.handoff-install-')
    try:
        with os.fdopen(fd,'wb') as f:
            f.write(raw);f.flush();os.fsync(f.fileno());os.fchmod(f.fileno(),stat.st_mode&0o777 if stat else 0o644)
            if stat:os.fchown(f.fileno(),stat.st_uid,stat.st_gid)
        os.replace(name,p)
    finally:Path(name).unlink(missing_ok=True)
def main():
    assert os.geteuid()==0,'Root required'
    root=Path('/opt/fh6/repo');store=Path('/var/lib/fh6');prepared={}
    for n,m in MANIFEST.items():
        p=root/n;assert not p.is_symlink(),'Unexpected symlink'
        before=p.read_bytes() if p.exists() else None
        sha=hashlib.sha256(before).hexdigest() if before is not None else None
        assert sha==m['old'],'Unexpected version: '+n+'; nothing changed'
        raw=base64.b64decode(m['body']);assert hashlib.sha256(raw).hexdigest()==m['new']
        if n.endswith('.py'):compile(raw,str(p),'exec')
        prepared[n]=(before,p.stat() if p.exists() else None,raw)
    lockpath=store/'runner.lock';assert not lockpath.is_symlink()
    with lockpath.open('rb') as lock:
        fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
        backup=store/'repairs'/('publish-diagnostics-'+str(time.time_ns()));backup.mkdir(mode=0o700)
        for n,(before,stat,raw) in prepared.items():
            if before is not None:
                saved=backup/n;saved.parent.mkdir(parents=True,exist_ok=True);saved.write_bytes(before);saved.chmod(0o600)
        applied=[]
        try:
            for n,(before,stat,raw) in prepared.items():replace(root/n,raw,stat);applied.append(n)
            subprocess.run(['/usr/bin/python3','-m','unittest','test_incident_reports','test_publisher_diagnostics','test_phone_tasks','test_phone_view','test_refresh_receipts','test_phone_csrf','test_editor_handoff','test_recovery','test_install_recovery'],cwd=root/'automation/server',check=True,timeout=120)
            subprocess.run(['runuser','-u','fh6','--','pwsh','-NoProfile','-Command',
                "$tokens=$null; $errors=$null; [System.Management.Automation.Language.Parser]::ParseFile('/opt/fh6/repo/automation/publish_to_github.ps1',[ref]$tokens,[ref]$errors) | Out-Null; if ($errors.Count) { exit 1 }; Write-Output 'PUBLISHER_SYNTAX=OK'"],cwd=root,check=True,timeout=30)
            subprocess.run(['/usr/bin/python3','automation/test_refresh_guard.py'],cwd=root,check=True,timeout=90)
            subprocess.run(['systemctl','restart','fh6-phone.service'],check=True,timeout=30)
            subprocess.run(['systemctl','is-active','--quiet','fh6-phone.service'],check=True,timeout=10)
        except Exception:
            for n in reversed(applied):
                before,stat,_=prepared[n]
                if before is None:(root/n).unlink(missing_ok=True)
                else:replace(root/n,before,stat)
            subprocess.run(['systemctl','restart','fh6-phone.service'],check=False,timeout=30)
            raise
        print('PUBLISH_DIAGNOSTICS_INSTALLED exact phase and historical error locations; no refresh or model task started',flush=True)
        print('BACKUP='+str(backup),flush=True)
        import sys,json
        sys.path.insert(0,str(root/'automation/server'))
        import incident_reports
        raw=incident_reports.regular(root,root/'automation/runs/refresh/active.json')
        if raw:
            try:
                active=json.loads(raw)
                run=incident_reports.load_run(root,active.get('runId',''))
                print(incident_reports.report(root,store,run)['text'],flush=True)
            except (ValueError,TypeError):print('LATEST_DIAGNOSTIC_UNAVAILABLE',flush=True)
if __name__=='__main__':main()
